#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.048441355, -0.1539177, -0.283096625], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.096966935, 'zmax': 0.096966935, 'profiles': [{'outer': [[-0.214335795, 0.12200665], [-0.216487085, 0.12740251], [-0.21691028499999998, 0.13244572], [-0.21620494499999998, 0.13840586], [-0.21437104499999998, 0.14517713], [-0.210703275, 0.15364128], [-0.204496255, 0.16467985999999998], [-0.195079925, 0.1782577], [-0.181819495, 0.19448053999999998], [-0.16467967499999997, 0.21197301], [-0.139322605, 0.23285115], [-0.11445930499999998, 0.24963826], [-0.085998725, 0.26466208999999996], [-0.05693864499999998, 0.27686447], [-0.030100354999999968, 0.28511703], [-0.003650025000000001, 0.28889054000000003], [0.02428148499999999, 0.28769141], [0.054364365000000026, 0.28056753], [0.08730380500000001, 0.26663697], [0.11798624499999999, 0.24872129999999998], [0.14140354500000002, 0.2296418], [0.15857862500000003, 0.21003329999999998], [0.170604755, 0.19042473999999998], [0.17758761500000003, 0.17261484], [0.17963306500000004, 0.15836694999999998], [0.17458991499999998, 0.15392327], [0.16020088500000002, 0.16552614999999998], [0.142073615, 0.18192535999999998], [0.12588600500000002, 0.19190597999999998], [0.117950905, 0.19176492], [0.124616375, 0.17769333999999998], [0.13770048499999998, 0.15378218999999999], [0.14895068500000003, 0.12391099], [0.15586303499999998, 0.08980769], [0.15607462500000002, 0.053059339999999997], [0.151983665, 0.014723989999999992], [0.146129295, -0.024175639999999998], [0.14136819500000003, -0.06166454000000002], [0.13960485500000003, -0.09675529999999999], [0.14048652500000003, -0.12634441000000002], [0.14362530500000004, -0.14736359999999998], [0.14877425500000002, -0.16341016000000003], [0.155580805, -0.17808124000000003], [0.164115475, -0.19127116], [0.17444871500000003, -0.20287406000000002], [0.18534623500000003, -0.21257252], [0.195538445, -0.22001389], [0.20832645654245036, -0.22793979963262628], [0.21341882500000003, -0.23055875000000003], [0.21691028499999998, -0.23422652], [0.21126757499999999, -0.23775324000000003], [0.19645540500000003, -0.24113888], [0.183018615, -0.24106833], [0.166972085, -0.23845854], [0.14940904500000002, -0.23306268000000002], [0.13145814500000003, -0.22569186000000002], [0.114177215, -0.21708667000000004], [0.10447104085437206, -0.2112806700423642], [0.113930335, -0.2243517], [0.126168055, -0.23704788], [0.14076863500000003, -0.24875656000000002], [0.156779875, -0.25820813000000004], [0.171556755, -0.26349822], [0.187391745, -0.26737759], [0.19984100500000002, -0.27012843000000003], [0.204778415, -0.2735846], [0.197901355, -0.27968583], [0.18259535500000001, -0.28564596000000003], [0.162140475, -0.28889054000000003], [0.13713608500000002, -0.28807938], [0.10811124500000002, -0.2819429], [0.075771315, -0.26931724], [0.050449595000000014, -0.25295332000000004], [0.029289294999999993, -0.23387381000000002], [0.011937905000000026, -0.21426529], [0.0038955726693632015, -0.20627468099791021], [0.0027716551874087435, -0.2090425364894213], [0.004990264999999994, -0.22167137000000003], [0.01482980500000003, -0.25196582], [0.01214949500000001, -0.25658581], [0.010809345000000026, -0.25633892], [0.0032269249999999916, -0.25316489000000003], [-0.008658125000000017, -0.24194995000000002], [-0.023047105000000012, -0.22255304000000004], [-0.035178984999999996, -0.19768974], [-0.043819424999999995, -0.17021665000000002], [-0.04752245499999999, -0.14344892000000004], [-0.047663504999999995, -0.11858562], [-0.04575908499999998, -0.09693161], [-0.042161855, -0.07764047000000002], [-0.03733020499999998, -0.059936390000000006], [-0.03368551281195812, -0.04286554833470078], [-0.03281600499999998, -0.021847930000000015], [-0.033874035, 0.005201939999999988], [-0.03669541499999998, 0.03038268999999999], [-0.041209544999999986, 0.053870559999999984], [-0.04738131499999998, 0.07577144999999999], [-0.054928485, 0.0957326], [-0.063639435, 0.11340143999999999], [-0.073373155, 0.12853103999999999], [-0.07585819209364764, 0.1313745685898737], [-0.083494815, 0.13974598], [-0.09478029499999999, 0.14849221999999998], [-0.10733538499999998, 0.15473452], [-0.121336425, 0.15794381], [-0.1340645040105385, 0.1575128255256274], [-0.149902775, 0.15357068], [-0.165772975, 0.14602357], [-0.180056165, 0.13713625], [-0.199347275, 0.12355839999999998], [-0.2031974070261237, 0.12190072637865015], [-0.20795244499999999, 0.11953797999999999], [-0.211761305, 0.11953797999999999]], 'holes': []}], 'simplify_tolerance': 0.00011555621600000002, 'sketch_entity_count': 140}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
